@pytest.mark.asyncio
async def test_extract_bytes_input() -> None:
    """extract bytes input from PDF document."""
    input = ExtractInput(
        bytes=Path("pdf/fake_memo.pdf").read_bytes(),
        filename="fake_memo.pdf",
        kind=ExtractInputKind("bytes"),
        mime_type="application/pdf",
    )

    result = await extract(input)
    assert _alef_e2e_text(result.results[0].mime_type).lower() == "application/pdf".lower()  # noqa: S101
